/** Helper – returns the blurDataURL for a given public path, or a neutral fallback. */
export function getBlur(publicPath: string): string {
  // Strip CDN prefix if present so we can match the local path key
  const key = publicPath.replace(/^https?:\/\/[^/]+/, '');
  return BLUR_DATA[key] ?? BLUR_DATA_FALLBACK;
}

